'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=> /^(https?:\/\/|(?:\/?(?:uploads|assets)\/))[\S]*$/i.test(String(v||''))?String(v):'';
const photo=p=>safeUrl(p.cover_image)||'assets/images/forest.jpg';
const types={hospital:'Hospital',police:'Police station',bus_station:'Bus station',shop:'Shop / store',vehicle_rental:'Vehicle rental',tuk_tuk:'Tuk-tuk driver',guide:'Local guide',other:'Other'};
const cats=['Nature','Waterfall','Temple','Tea estate','Historical','Viewpoint'];
const state={user:null,csrf:'',places:[],planIds:new Set(),generated:null,admin:null,routeToken:0};
let toastTimer, mapInstance;
async function api(action,data=null,params={}){const options={credentials:'same-origin',headers:{}};if(data!==null){options.method='POST';options.headers['X-CSRF-Token']=state.csrf;if(data instanceof FormData)options.body=data;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}const response=await fetch('api.php?'+new URLSearchParams({action,...params}),options);let body;try{body=await response.json();}catch{throw new Error('The server could not complete this request. Please try again.');}if(!response.ok||!body.ok){const error=new Error(body.error||'Something went wrong. Please try again.');error.errors=body.errors;error.status=response.status;throw error;}return body.data;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',5000);}
function formError(form,error){let box=$('.form-error',form);if(!box){box=document.createElement('div');box.className='form-error';box.setAttribute('role','alert');form.prepend(box);}box.textContent=error.message+(error.errors?' '+Object.values(error.errors).join(' '):'');box.tabIndex=-1;box.focus();}
async function submit(form,action,data,onSuccess){const button=$('[type=submit]',form);if(button)button.disabled=true;const box=$('.form-error',form);if(box)box.textContent='';try{const result=await api(action,data);await onSuccess(result);}catch(error){formError(form,error);}finally{if(button)button.disabled=false;}}
function values(form){return Object.fromEntries(new FormData(form));}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
function pageHead(title,description,eyebrow='A LITTLE CLOSER TO NATURE'){return `<div class="page-head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>`;}
function empty(title,description,link='',label='Discover places'){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(description)}</p>${link?`<a class="button" href="#${esc(link)}">${esc(label)} →</a>`:''}</div>`;}
function badge(status){return `<span class="badge ${esc(status)}">${esc(status)}</span>`;}
function nav(){const r=location.hash.split('/')[0]||'#home';$('#navigation').innerHTML=`<a class="${['#home','#explore','#place'].includes(r)?'active':''}" href="#explore">Discover places</a><a class="${r==='#planner'?'active':''}" href="#planner">Plan your escape</a><a class="${r==='#care'?'active':''}" href="#care">Travel gently</a>${state.user?`<a href="#account">${esc(state.user.name.split(' ')[0])}'s space</a>${state.user.role==='admin'?'<a href="#admin">Admin</a>':''}`:'<a href="#login">Log in</a>'}<a class="button" href="#submit">Share a place <span>↗</span></a>`;$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function card(p){return `<article class="place-card"><div class="card-photo"><a href="#place/${p.id}" tabindex="-1" aria-hidden="true"><img src="${esc(photo(p))}" alt="${esc(p.title)} — illustrative destination photo" loading="lazy"></a><span class="badge">${esc(p.category)}</span><button class="icon-button save-button ${p.is_saved?'saved':''}" data-save="${p.id}" aria-label="${p.is_saved?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${p.is_saved?'true':'false'}">${p.is_saved?'♥':'♡'}</button></div><div class="card-body"><div class="card-region">⌖ &nbsp;${esc(p.region)} · Sri Lanka</div><h3><a href="#place/${p.id}">${esc(p.title)}</a></h3><p>${esc(p.description)}</p><div class="card-bottom"><span>◷ ${esc(p.visit_minutes||60)} min visit &nbsp; · &nbsp;${esc(p.difficulty||'Check access')}</span><a href="#place/${p.id}" aria-label="Explore ${esc(p.title)}">↗</a></div></div></article>`;}
function bindSaves(){ $$('[data-save]').forEach(button=>button.onclick=async()=>{if(!state.user){toast('Log in to keep your favourite places.');go('login');return;}button.disabled=true;try{await api('save_toggle',{place_id:Number(button.dataset.save)});const saved=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(saved));button.classList.toggle('saved',saved);button.textContent=saved?'♥':'♡';toast(saved?'Added to your saved places.':'Removed from saved places.');if(location.hash==='#saved')render();}catch(e){toast(e.message,true);}finally{button.disabled=false;}});}
function categoryOptions(categories=cats,selected=''){return `<option value="">All landscapes</option>`+categories.map(c=>`<option ${c===selected?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('');}
async function home(){const data=await api('places',null,{page:1});state.places=data.items;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">OFF THE USUAL PATH. INTO SOMETHING REAL.</div><h1>Less noise.<br>More <em>nature.</em></h1><p>Find the hidden waterfalls, quiet trails and little wonders around Makandura. Your next deep breath is closer than you think.</p><div class="hero-actions"><a class="button lime" href="#explore">Find your escape <span>↗</span></a><a class="button white" href="#planner">Plan a day out <span>→</span></a></div></div><div class="hero-note">FOR THE WANDERERS. THE SLOW TRAVELLERS. YOU.</div><div class="hero-location"><span>⌖</span><div>THE QUIETER SIDE OF<br><strong>Makandura, Sri Lanka</strong></div></div></section><form id="home-search" class="search-bar"><label>Where does your mind wander?<input name="q" placeholder="Waterfalls, forest paths, a quiet corner…" aria-label="Search places"></label><label>Your kind of escape<select name="category">${categoryOptions(data.categories)}</select></label><label>Somewhere nearby<input name="region" placeholder="Makandura & beyond"></label><button class="button" type="submit">Explore places <span>↗</span></button></form><div class="intro-strip"><span><b>⌖</b> Hidden gems, close to home</span><span><b>♧</b> Shared by curious travellers</span><span><b>♡</b> Nature first. Always.</span></div><div class="container"><section class="section"><div class="section-heading"><div><div class="eyebrow">GOOD PLACES. BETTER MEMORIES.</div><h2>Your next happy place.</h2><p>A little less discovered. A lot more worth the journey.</p></div><a class="text-link" href="#explore">Explore all places <span>↗</span></a></div><div class="chips"><a class="chip active" href="#explore">✧ All escapes</a>${(data.categories||cats).slice(0,5).map((c,i)=>`<a class="chip" href="#explore?category=${encodeURIComponent(c)}">${['♧','≈','⌂','↟','☀'][i]} ${esc(c)}</a>`).join('')}</div><div class="grid">${data.items.slice(0,6).map(card).join('')||empty('The trail starts here','Be the first to share a thoughtfully documented place.','submit','Share a place')}</div></section><section class="nature-panel"><div class="nature-art"><span>Leave only footprints. Take a little wonder.</span></div><div class="nature-copy"><div class="eyebrow">KEEP THE HIDDEN PLACES SPECIAL</div><h2>A beautiful escape.<br>A lighter footprint.</h2><p>These places are someone's home. Let's keep the rivers clear, the trails quiet, and the welcome warm.</p><div class="care-points"><span>♧ Carry your waste</span><span>♡ Respect local life</span><span>↟ Stay on the trail</span></div><a class="text-link" href="#care">Our promise to nature <span>↗</span></a></div></section><section class="cta-panel"><div><h3>Know a place that deserves a little love?</h3><p>Share your discovery. Help someone find their kind of quiet.</p></div><a class="button lime" href="#submit">Share a hidden gem <span>↗</span></a></section></div>`;}
function bindHome(){$('#home-search').onsubmit=e=>{e.preventDefault();go('explore?'+new URLSearchParams(values(e.target)));};bindSaves();}
async function explore(params){const data=await api('places',null,Object.fromEntries(params));state.places=data.items;return `<div class="container">${pageHead('Take the scenic route.','Find a little wilderness, a story worth hearing, or simply somewhere to slow down.')}<form id="filters" class="filter-form"><label>Search places<input name="q" value="${esc(params.get('q'))}" placeholder="Name or keyword"></label><label>Category<select name="category">${categoryOptions(data.categories,params.get('category'))}</select></label><label>Region<input name="region" value="${esc(params.get('region'))}" placeholder="Any nearby region"></label><label>Sort by<select name="sort"><option value="newest">Recently shared</option><option value="name" ${params.get('sort')==='name'?'selected':''}>Name A–Z</option></select></label><button class="button" type="submit">Find places →</button><label>Within (km)<input name="radius" type="number" min="1" max="500" value="${esc(params.get('radius')||25)}"></label><div class="inline-actions"><button class="button secondary small" id="near-me" type="button">⌖ Near me</button><a class="text-link" href="#explore">Clear filters</a></div><input type="hidden" name="lat" value="${esc(params.get('lat'))}"><input type="hidden" name="lng" value="${esc(params.get('lng'))}"></form><div class="toolbar"><span class="muted">${data.total} ${data.total===1?'place':'places'} to pause a little longer</span><div class="inline-actions"><button class="chip active" id="grid-view">▦ List view</button><button class="chip" id="map-view">⌖ Map view</button></div></div><div id="explore-map" class="map" hidden></div><div class="grid" id="place-grid">${data.items.map(card).join('')||empty('No places on this trail yet','Try another keyword or region. Clear the filters to see every place.','explore','Clear filters')}</div><div class="pagination">${Array.from({length:data.pages||1},(_,i)=>`<a class="chip ${Number(params.get('page')||1)===i+1?'active':''}" href="#explore?${esc(new URLSearchParams({...Object.fromEntries(params),page:i+1}).toString())}">${i+1}</a>`).join('')}</div></div>`;}
function bindExplore(){bindSaves();$('#filters').onsubmit=e=>{e.preventDefault();const data=values(e.target);if(!data.lat||!data.lng){delete data.lat;delete data.lng;delete data.radius;}go('explore?'+new URLSearchParams(data));};$('#near-me').onclick=()=>{if(!navigator.geolocation){toast('Location is unavailable. Search by region instead.',true);return;}toast('Waiting for your location permission…');navigator.geolocation.getCurrentPosition(pos=>{const f=$('#filters');f.elements.lat.value=pos.coords.latitude;f.elements.lng.value=pos.coords.longitude;f.requestSubmit();},()=>toast('Location could not be read. Search by region instead.',true),{timeout:15000});};$('#map-view').onclick=()=>{$('#explore-map').hidden=false;$('#place-grid').hidden=true;$('#map-view').classList.add('active');$('#grid-view').classList.remove('active');makeMap('explore-map',state.places);};$('#grid-view').onclick=()=>{$('#explore-map').hidden=true;$('#place-grid').hidden=false;$('#grid-view').classList.add('active');$('#map-view').classList.remove('active');};}
function makeMap(id,places,services=[]){const el=$('#'+id);if(!el)return;if(mapInstance){mapInstance.remove();mapInstance=null;}if(!window.L){el.innerHTML='<div class="map-fallback">Interactive map unavailable. Coordinates and navigation links remain available in each place.</div>';return;}mapInstance=L.map(el).setView([6.145,80.566],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(mapInstance);const points=[];[...places,...services].forEach(p=>{if(p.latitude===null||p.longitude===null||p.latitude===''||p.longitude===''||!Number.isFinite(Number(p.latitude))||!Number.isFinite(Number(p.longitude)))return;const coords=[Number(p.latitude),Number(p.longitude)];points.push(coords);L.marker(coords).addTo(mapInstance).bindPopup(p.title?`<a href="#place/${Number(p.id)}"><strong>${esc(p.title)}</strong></a><br>${esc(p.category)}`:`<strong>${esc(p.name)}</strong><br>${esc(types[p.type]||p.type)}`);});if(points.length)mapInstance.fitBounds(points,{padding:[35,35],maxZoom:14});setTimeout(()=>mapInstance?.invalidateSize(),50);}
function serviceCard(s){return `<article class="service-card">${badge(types[s.type]||s.type)} ${Number(s.is_sponsored)?'<span class="badge sponsored">Paid promotion</span>':''}<h3>${esc(s.name)}</h3><p>${esc(s.description||'Additional details not supplied.')}</p><p>${esc(s.address||'Address not supplied.')}</p><div class="inline-actions">${s.phone?`<a href="tel:${esc(String(s.phone).replace(/[^+\d]/g,''))}">${esc(s.phone)}</a>`:'<small class="muted">Contact not verified / not supplied</small>'}${safeUrl(s.website)?`<a href="${esc(safeUrl(s.website))}" target="_blank" rel="noopener noreferrer">Website ↗</a>`:''}${s.latitude&&s.longitude?`<a href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(s.latitude)}&mlon=${encodeURIComponent(s.longitude)}#map=16/${encodeURIComponent(s.latitude)}/${encodeURIComponent(s.longitude)}" target="_blank" rel="noopener noreferrer">Map ↗</a>`:''}</div></article>`;}
async function detail(id){const p=await api('place',null,{id});state.currentPlace=p;const images=p.images?.length?p.images:[{path:photo(p),caption:p.title}];return `<div class="container"><div class="page-head"><a class="text-link" href="#explore">← Back to discoveries</a></div><div class="detail-header"><div>${badge(p.category)} ${p.status!=='approved'?badge(p.status):''}<h1>${esc(p.title)}</h1><p>⌖ ${esc(p.region)} · Shared by ${esc(p.author_name||'the community')}</p></div><div class="inline-actions"><button class="button secondary" data-save="${p.id}" aria-label="Save ${esc(p.title)}" aria-pressed="${p.is_saved?'true':'false'}">${p.is_saved?'♥ Saved':'♡ Save place'}</button><button class="button" id="add-plan">Add to day plan +</button></div></div><div class="detail-gallery ${images.length<2?'single':''}">${images.slice(0,2).map((im,i)=>`<button data-gallery="${i}" aria-label="Open photo ${i+1} of ${esc(p.title)}"><img src="${esc(safeUrl(im.path)||photo(p))}" alt="${esc(im.caption||p.title)}"></button>`).join('')}</div>${images.length>2?`<button class="button secondary small" data-gallery="0">View all ${images.length} photos</button>`:''}<div class="notice warning">Demonstration catalogue: destination details, access and imagery require local verification before travel. ${p.updated_at?'Last updated '+esc(String(p.updated_at).slice(0,10))+'.':''}</div><div class="detail-layout"><div><section><h2>A little about this place</h2><p>${esc(p.description)}</p></section><section><h2>Getting here from Colombo</h2><p>${esc(p.route_from_colombo)}</p><a class="button secondary small" href="https://www.google.com/maps/dir/?api=1&origin=Colombo%2C+Sri+Lanka&destination=${encodeURIComponent(p.latitude+','+p.longitude)}" target="_blank" rel="noopener noreferrer">Open directions from Colombo ↗</a></section><section><h2>Find your way</h2><p>Map coordinates: ${esc(p.latitude)}, ${esc(p.longitude)}. Confirm the final approach locally.</p><div id="detail-map" class="map map-small"></div><a class="text-link" href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(p.latitude)}&mlon=${encodeURIComponent(p.longitude)}#map=15/${encodeURIComponent(p.latitude)}/${encodeURIComponent(p.longitude)}" target="_blank" rel="noopener noreferrer">Open location on OpenStreetMap ↗</a></section><section class="conservation"><div class="eyebrow">LEAVE IT LOVELIER</div><h3>This place needs your care.</h3><p>${esc(p.conservation_notes)}</p><a class="text-link" href="#care">Read the nature promise →</a></section><section><h2>Local essentials & friendly faces</h2><p>Check opening hours and contact details before relying on a service. Paid promotion is labelled and does not mean safety verification.</p><div class="service-grid">${(p.services||[]).map(serviceCard).join('')||'<div class="notice">No nearby services have been verified or supplied for this place.</div>'}</div><p class="help">${Object.entries(types).filter(([type])=>!(p.services||[]).some(s=>s.type===type)).map(([,name])=>esc(name)).join(', ')}: details not supplied. Do not assume these services are nearby or available.</p></section></div><aside><section class="side-panel"><div class="eyebrow">BEFORE YOU SET OFF</div><h3>A slower kind of adventure</h3><dl class="facts"><div><dt>Time to explore</dt><dd>${esc(p.visit_minutes)} minutes</dd></div><div><dt>Best time</dt><dd>${esc(p.best_time||'Check locally')}</dd></div><div><dt>Trail difficulty</dt><dd>${esc(p.difficulty||'Not supplied')}</dd></div><div><dt>Entry fee</dt><dd>${esc(p.entry_fee||'Confirm locally')}</dd></div></dl><p><strong>Opening hours</strong><br>${esc(p.opening_hours||'Confirm locally before travelling.')}</p><p><strong>Accessibility & permission</strong><br>${esc(p.accessibility||'Access conditions are not supplied. Contact a local source first.')}</p>${p.contact?`<p><strong>Place contact</strong><br>${esc(p.contact)}</p>`:''}</section><section class="side-panel"><h3>Stay curious. Stay safe.</h3><p>${esc(p.safety_notes)}</p><p>Weather, roads and access can change. Travel with enough water, daylight and a way to contact help.</p><button class="button secondary" id="report-place">Report outdated or unsafe information</button></section>${state.user&&(state.user.role==='admin'||Number(p.user_id||p.author_id)===Number(state.user.id))?`<a class="button secondary" href="#submit/${p.id}">Edit this place →</a>`:''}</aside></div></div>`;}
function bindDetail(){bindSaves();const p=state.currentPlace;makeMap('detail-map',[p],p.services||[]);$('#add-plan').onclick=()=>{state.planIds.add(Number(p.id));go('planner');};$$('[data-gallery]').forEach(b=>b.onclick=()=>showGallery(Number(b.dataset.gallery)));$('#report-place').onclick=()=>modal(`<h2>Help keep this place accurate</h2><p>Tell the administrator what needs checking. For an immediate emergency, contact local emergency services directly.</p><form id="report-form"><label>What should we check?<textarea name="reason" required minlength="10" maxlength="2000" placeholder="Describe the incorrect detail, access problem or concern…"></textarea></label><div class="form-error" role="alert"></div><button class="button" type="submit">Send report</button></form>`,()=>$('#report-form').onsubmit=e=>{e.preventDefault();submit(e.target,'report',{place_id:p.id,...values(e.target)},()=>{closeModal();toast('Thank you. The administrator will review your report.');});});}
function showGallery(index){const p=state.currentPlace, images=p.images?.length?p.images:[{path:photo(p),caption:p.title}];const im=images[index];modal(`<img class="modal-image" src="${esc(safeUrl(im.path)||photo(p))}" alt="${esc(im.caption||p.title)}"><p>${esc(im.caption||p.title)} · ${index+1} / ${images.length}</p><div class="inline-actions"><button class="button secondary" id="previous-photo" ${index===0?'disabled':''}>← Previous</button><button class="button secondary" id="next-photo" ${index===images.length-1?'disabled':''}>Next →</button></div>`,()=>{$('#previous-photo').onclick=()=>showGallery(index-1);$('#next-photo').onclick=()=>showGallery(index+1);});}
function modal(content,bind=()=>{}){$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();bind();}function closeModal(){$('#modal').close();}
function auth(register=false){return `<div class="auth-layout"><div class="auth-art"><div class="eyebrow">MORE THAN A DESTINATION</div><h2>Find your people.<br>Share your places.</h2><p>A community of curious souls who believe the best journeys leave a lighter footprint.</p></div><div class="auth-form"><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>${register?'Join the wanderers.':'Welcome back.'}</h1><p>${register?'Save your favourites and share a hidden gem.':'Your quiet corners are waiting for you.'}</p><form id="auth-form">${register?'<label>Your name<input name="name" autocomplete="name" required minlength="2" maxlength="100"></label>':''}<label>Email address<input name="email" type="email" autocomplete="email" required maxlength="190"></label><label>Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="${register?'10':'1'}" maxlength="200">${register?'<small>At least 10 characters. Use a unique password.</small>':''}</label><div class="form-error" role="alert"></div><button class="button" type="submit">${register?'Create my account':'Log in'} →</button></form><p class="help" style="margin-top:20px">${register?'Already part of the journey? <a class="text-link" href="#login">Log in</a>':'New around here? <a class="text-link" href="#register">Create an account</a>'}</p><a class="text-link" href="#explore">Keep exploring as a visitor →</a></div></div>`;}
function bindAuth(register){$('#auth-form').onsubmit=e=>{e.preventDefault();submit(e.target,register?'register':'login',values(e.target),async()=>{const session=await api('session');Object.assign(state,session);toast(register?'Your account is ready. Welcome to Offbeat.':'Welcome back.');go('account');});};}
function accountTabs(active){return `<div class="tabs"><a href="#account" class="${active==='account'?'active':''}">My places</a><a href="#saved" class="${active==='saved'?'active':''}">Saved places</a><a href="#plans" class="${active==='plans'?'active':''}">My day plans</a><a href="#profile" class="${active==='profile'?'active':''}">Profile</a><button class="chip" id="logout">Log out</button></div>`;}
async function account(view){if(!state.user)return auth();let content='';if(view==='profile'){content=`<form id="profile-form" class="form-section" style="max-width:650px"><h2>Your details</h2><div class="form-grid"><label>Your name<input name="name" required minlength="2" value="${esc(state.user.name)}"></label><label>Email<input name="email" type="email" required value="${esc(state.user.email)}"></label><label>Current password<input name="current_password" type="password" autocomplete="current-password"><small>Required to change email or password.</small></label><label>New password (optional)<input name="new_password" type="password" minlength="10" autocomplete="new-password"></label></div><div class="form-error" role="alert"></div><button class="button" type="submit">Save profile</button></form>`;}else if(view==='saved'){const items=await api('saved');content=`<div class="grid">${items.map(card).join('')||empty('Keep a little inspiration','Tap the heart on any place to save it here.','explore')}</div>`;}else if(view==='plans'){const plans=await api('plans');state.savedPlans=plans;content=`<div class="account-grid">${plans.map(p=>`<article class="my-card"><div class="eyebrow">A DAY TO LOOK FORWARD TO</div><h3>${esc(p.name)}</h3><p>Start ${esc(p.start_time||'07:00')} · Saved ${esc(String(p.created_at||'').slice(0,10))}</p><div class="inline-actions"><button class="button small" data-load-plan="${p.id}">Open plan</button><button class="button danger small" data-delete-plan="${p.id}">Delete</button></div></article>`).join('')||empty('Make room for a day outside','Build your first day plan and save it for later.','planner','Plan a day')}</div>`;}else{const places=await api('my_places');content=`<div class="toolbar"><p>Every contribution helps someone discover a quieter corner.</p><a class="button" href="#submit">Share a place +</a></div><div class="account-grid">${places.map(p=>`<article class="my-card">${badge(p.status)}<h3>${esc(p.title)}</h3><p>${esc(p.region)}</p>${p.moderation_note?`<div class="notice">Review note: ${esc(p.moderation_note)}</div>`:''}<div class="inline-actions"><a class="button secondary small" href="#place/${p.id}">Preview</a><a class="button small" href="#submit/${p.id}">Edit</a><button class="button danger small" data-delete-place="${p.id}">Delete</button></div></article>`).join('')||empty('Your first discovery belongs here','Add photos, directions and thoughtful advice. An administrator reviews each submission.','submit','Share a place')}</div>`;}return `<div class="container">${pageHead('Hello, '+state.user.name.split(' ')[0]+'.','A little collection of places, plans and possibilities.','YOUR WANDERER’S SPACE')}${accountTabs(view)}${content}</div>`;}
function bindAccount(view){if(!state.user){bindAuth(false);return;}bindSaves();$('#logout').onclick=async()=>{try{await api('logout',{});Object.assign(state,await api('session'));go('home');toast('You are logged out.');}catch(e){toast(e.message,true);}};if(view==='profile')$('#profile-form').onsubmit=e=>{e.preventDefault();submit(e.target,'profile',values(e.target),async()=>{Object.assign(state,await api('session'));toast('Profile updated.');render();});};$$('[data-delete-place]').forEach(b=>b.onclick=()=>confirmAction('Delete this place?','Its photos and associated information will also be removed.',async()=>{await api('delete_place',{id:Number(b.dataset.deletePlace)});toast('Place deleted.');render();}));$$('[data-delete-plan]').forEach(b=>b.onclick=()=>confirmAction('Delete this saved plan?','You can always create another day out.',async()=>{await api('plan_delete',{id:Number(b.dataset.deletePlan)});render();}));$$('[data-load-plan]').forEach(b=>b.onclick=()=>{const p=state.savedPlans.find(p=>Number(p.id)===Number(b.dataset.loadPlan));let ids=p.place_ids;if(typeof ids==='string'){try{ids=JSON.parse(ids);}catch{ids=[];}}state.planIds=new Set((ids||[]).map(Number));state.loadedPlan=p;go('planner');});}
function confirmAction(title,description,callback){modal(`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="form-error" role="alert"></div><div class="form-actions"><button class="button danger" id="confirm-action">Confirm</button><button class="button secondary" id="cancel-action">Cancel</button></div>`,()=>{$('#cancel-action').onclick=closeModal;$('#confirm-action').onclick=async e=>{e.target.disabled=true;try{await callback();closeModal();}catch(error){$('.form-error',$('#modal')).textContent=error.message;e.target.disabled=false;}};});}
const field=(name,label,value='',options='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" ${options}></label>`;
const area=(name,label,value='',options='')=>`<label class="full">${esc(label)}<textarea name="${name}" ${options}>${esc(value)}</textarea></label>`;
function serviceFields(s={}){return `<div class="service-row" data-id="${esc(s.id||'')}"><div class="form-grid"><label>Service type<select data-field="type">${Object.entries(types).map(([v,t])=>`<option value="${v}" ${s.type===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Name<input data-field="name" value="${esc(s.name)}" required maxlength="160"></label><label>Phone (if verified)<input data-field="phone" value="${esc(s.phone)}" maxlength="50"></label><label>Address<input data-field="address" value="${esc(s.address)}" maxlength="500"></label><label class="full">Details<textarea data-field="description" maxlength="2000">${esc(s.description)}</textarea></label><label>Latitude (optional)<input data-field="latitude" type="number" min="-90" max="90" step="any" value="${esc(s.latitude)}"></label><label>Longitude (optional)<input data-field="longitude" type="number" min="-180" max="180" step="any" value="${esc(s.longitude)}"></label><label class="full">Website (optional)<input data-field="website" type="url" value="${esc(s.website)}" placeholder="https://"></label></div><button type="button" class="button danger small remove-service" style="margin-top:12px">Remove service</button>${Number(s.is_sponsored)?'<small class="help">An active paid listing is managed by the administrator.</small>':''}</div>`;}
async function placeForm(id){if(!state.user)return auth();const p=id?await api('place',null,{id}):{};state.editPlace=p;const categories=Array.from(new Set([...cats,...state.places.map(p=>p.category),p.category].filter(Boolean)));return `<div class="container">${pageHead(id?'Give your place a little care.':'Some places are too good to keep to yourself.',id?'Keep the details useful, honest and up to date.':'Share what makes it special, how to get there, and how to leave it just as beautiful.','SHARE A HIDDEN GEM')}<div class="notice">${state.user.role==='admin'?'Administrator contributions can be published immediately.':'An administrator reviews every contribution before publication. Editing a published place sends it back for review.'} Fields marked * are required. Do not publish private land, sensitive wildlife locations or personal contacts without permission.</div><form id="place-form" enctype="multipart/form-data"><div class="form-section"><h2>01 · Tell its story</h2><div class="form-grid">${field('title','Place name *',p.title,'required minlength="3" maxlength="160"')}<label>Category *<select name="category" required><option value="">Choose a category</option>${categories.map(c=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('region','Region / nearest village *',p.region,'required maxlength="120"')}${field('best_time','Best time to visit',p.best_time,'maxlength="160"')}${area('description','Description & cultural or natural significance *',p.description,'required minlength="30" maxlength="15000"')}</div></div><div class="form-section"><h2>02 · Help someone find it</h2><div class="form-grid">${field('latitude','Latitude *',p.latitude,'required type="number" min="-90" max="90" step="any"')}${field('longitude','Longitude *',p.longitude,'required type="number" min="-180" max="180" step="any"')}<div class="full"><button type="button" class="button secondary small" id="submission-location">Use my current location</button><small class="help">Use the actual public entrance coordinates, not your home. You can copy them from OpenStreetMap.</small></div>${area('route_from_colombo','Route from Colombo, including the final approach *',p.route_from_colombo,'required minlength="20" maxlength="10000"')}${field('visit_minutes','Suggested visit duration (minutes) *',p.visit_minutes||60,'required type="number" min="15" max="720"')}<label>Difficulty<select name="difficulty">${['Easy','Moderate','Challenging'].map(v=>`<option ${String(p.difficulty).toLowerCase()===v.toLowerCase()?'selected':''}>${v}</option>`).join('')}</select></label>${field('opening_hours','Opening hours',p.opening_hours,'maxlength="250"')}${field('entry_fee','Entry fee / permission cost',p.entry_fee,'maxlength="250"')}${area('accessibility','Accessibility, permissions & access restrictions',p.accessibility,'maxlength="3000"')}${field('contact','Public place contact (with permission)',p.contact,'maxlength="250"')}</div></div><div class="form-section"><h2>03 · Protect the place and its visitors</h2><div class="form-grid">${area('conservation_notes','Conservation guidance *',p.conservation_notes,'required minlength="20" maxlength="5000"')}${area('safety_notes','Safety, terrain, weather & seasonal risks *',p.safety_notes,'required minlength="20" maxlength="5000"')}</div></div><div class="form-section"><h2>04 · A window into your discovery</h2><p class="help">Add 1–8 JPEG, PNG or WebP photos, up to 5 MB each. Upload images you own or have permission to publish.</p>${p.images?.length?`<div class="image-checks">${p.images.map(im=>`<label><img src="${esc(safeUrl(im.path))}" alt="Existing photo"><input type="checkbox" name="remove_image_ids[]" value="${im.id}">Remove photo</label>`).join('')}</div>`:''}<label>Photos ${id?'(optional unless removing all existing photos)':'*'}<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple ${id?'':'required'}></label><div id="image-preview" class="image-checks" style="margin-top:15px"></div></div><div class="form-section"><h2>05 · Local essentials & helpful people</h2><p>Hospitals, police, bus stations, shops, rentals, tuk-tuk drivers and guides. Add only information you know; unknown details can stay empty.</p><div id="service-rows">${(p.services||[]).map(serviceFields).join('')}</div><button class="button secondary" type="button" id="add-service">Add a nearby service +</button></div>${state.user.role==='admin'?`<div class="form-section"><label>Publication status<select name="status"><option value="approved" ${p.status==='approved'?'selected':''}>Approved</option><option value="pending" ${p.status==='pending'?'selected':''}>Pending review</option><option value="rejected" ${p.status==='rejected'?'selected':''}>Rejected</option></select></label></div>`:''}<label><input type="checkbox" required>I have permission to share these photos and contact details, and will help protect this place.</label><div class="form-error" role="alert"></div><div class="form-actions"><button class="button" type="submit">${state.user.role==='admin'?'Save place':'Submit for review'} ↗</button><a class="button secondary" href="#account">Cancel</a></div></form></div>`;}
function bindPlaceForm(){if(!state.user){bindAuth(false);return;}const form=$('#place-form');const bindRemove=()=>$$('.remove-service',form).forEach(b=>b.onclick=()=>b.closest('.service-row').remove());bindRemove();$('#add-service').onclick=()=>{if($$('.service-row',form).length>=20){toast('Please limit this submission to 20 nearby services.',true);return;}$('#service-rows').insertAdjacentHTML('beforeend',serviceFields());bindRemove();};$('#submission-location').onclick=()=>{if(!navigator.geolocation){toast('Location is unavailable. Enter coordinates manually.',true);return;}navigator.geolocation.getCurrentPosition(p=>{form.elements.latitude.value=p.coords.latitude.toFixed(6);form.elements.longitude.value=p.coords.longitude.toFixed(6);},()=>toast('Location unavailable. Enter coordinates manually.',true),{timeout:15000});};form.elements['images[]'].onchange=e=>{$('#image-preview').replaceChildren();[...e.target.files].forEach(file=>{if(!file.type.startsWith('image/'))return;const img=document.createElement('img');img.style.cssText='width:100px;height:80px;object-fit:cover;border-radius:8px';img.alt=file.name;img.src=URL.createObjectURL(file);img.onload=()=>URL.revokeObjectURL(img.src);$('#image-preview').append(img);});};form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);if(state.editPlace.id)data.set('id',state.editPlace.id);const removed=data.getAll('remove_image_ids[]');data.delete('remove_image_ids[]');data.set('remove_image_ids',JSON.stringify(removed.map(Number)));const services=$$('.service-row',form).map(row=>{const result={};if(row.dataset.id)result.id=Number(row.dataset.id);$$('[data-field]',row).forEach(input=>result[input.dataset.field]=input.value);return result;});data.set('services_json',JSON.stringify(services));submit(form,'save_place',data,()=>{toast(state.user.role==='admin'?'Place saved.':'Your place has been sent for review.');go(state.user.role==='admin'?'admin/places':'account');});};}
async function allPlaces(){const first=await api('places',null,{page:1});let items=first.items;for(let page=2;page<=Math.min(first.pages,20);page++){const next=await api('places',null,{page});items.push(...next.items);}return items;}
async function planner(){const items=await allPlaces();state.plannerPlaces=items;const old=state.loadedPlan||{};return `<div class="container">${pageHead('One day. A world away.','Pick a few places, and we’ll suggest a simple order for your day. Leave a little space for the unexpected.','PLAN YOUR ESCAPE')}<div class="planner-layout"><form id="planner-form"><div class="form-section"><h2>01 · Pick your little adventures</h2><p class="help">Choose up to 12 places. A relaxed day often works best with 2–4.</p><div class="plan-options">${items.map(p=>`<label class="plan-choice"><input type="checkbox" name="place_ids" value="${p.id}" ${state.planIds.has(Number(p.id))?'checked':''}><img src="${esc(photo(p))}" alt=""><span>${esc(p.title)}<small>${esc(p.region)} · ${p.visit_minutes} min visit</small></span></label>`).join('')||empty('No places to plan yet','Check back when the first place has been approved.')}</div></div><div class="form-section"><h2>02 · Where does your day begin?</h2><p class="help">Colombo is the default starting point. Set your own coordinates if you are already nearby. Times use Sri Lanka local time.</p><div class="form-grid">${field('start_lat','Start latitude',old.start_lat||6.9271,'type="number" min="-90" max="90" step="any" required')}${field('start_lng','Start longitude',old.start_lng||79.8612,'type="number" min="-180" max="180" step="any" required')}${field('start_time','Departure time',old.start_time||'07:00','type="time" required')}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="button" type="submit">Build my day plan →</button></div></div></form><div id="plan-result">${empty('A good day starts with a little curiosity','Choose your places and departure time. Your suggested itinerary will appear here.')}</div></div></div>`;}
function planInput(form){const f=new FormData(form);return{place_ids:f.getAll('place_ids').map(Number),start_lat:Number(f.get('start_lat')),start_lng:Number(f.get('start_lng')),start_time:f.get('start_time')};}
function bindPlanner(){const form=$('#planner-form');form.onchange=()=>{state.planIds=new Set(planInput(form).place_ids);state.generated=null;$('#plan-result').innerHTML=empty('Your plans changed','Build the day plan again to update the order and estimated times.');};form.onsubmit=e=>{e.preventDefault();const data=planInput(form);state.planIds=new Set(data.place_ids);submit(form,'plan_generate',data,result=>{state.generated={...result,input:data};showPlan();});};if(state.loadedPlan){state.loadedPlan=null;form.requestSubmit();}}
function showPlan(){const result=state.generated;$('#plan-result').innerHTML=`<div class="form-section"><div class="eyebrow">YOUR DAY, AT A GENTLER PACE</div><h2>The scenic way around.</h2><p>${esc(result.total_km)} km estimated · ${Math.floor(result.total_minutes/60)}h ${Math.round(result.total_minutes%60)}m</p><div class="notice warning">${esc(result.warning||'Approximate distances and timings, not live road navigation. Allow extra time for breaks, road conditions and the return trip.')}</div>${result.stops.map((p,i)=>`<article class="plan-stop"><small>${esc(p.arrival_time)} – ${esc(p.departure_time)}</small><h3>${i+1}. <a href="#place/${p.id}">${esc(p.title)}</a></h3><p>${esc(p.leg_km)} km estimated from previous stop · ${esc(p.visit_minutes)} min visit</p><a class="text-link" href="#place/${p.id}">Directions, safety & local essentials ↗</a></article>`).join('')}<p class="help">${esc(result.method||'Nearest-neighbour geographic estimate')} · Return journey is not included. Check real road directions and weather before setting off.</p>${state.user?`<form id="save-plan-form">${field('name','Give this day a name','My Makandura escape','required minlength="2" maxlength="150"')}<div class="form-error" role="alert"></div><button class="button" style="margin-top:15px" type="submit">Save my day plan ♡</button></form>`:'<a class="button" href="#login">Log in to save this plan →</a>'}</div>`;if(state.user)$('#save-plan-form').onsubmit=e=>{e.preventDefault();submit(e.target,'plan_save',{...result.input,name:e.target.elements.name.value},()=>toast('Your day plan is saved in your space.'));};}
async function services(params){const items=await api('services',null,Object.fromEntries(params));state.serviceItems=items;return `<div class="container">${pageHead('A little local knowledge.','Find essential services, friendly guides and local businesses. Always confirm details before you travel.','LOCAL ESSENTIALS')}<form id="services-filter" class="filter-form"><label>Search name or details<input name="q" value="${esc(params.get('q'))}" placeholder="What do you need?"></label><label>Service type<select name="type"><option value="">All services</option>${Object.entries(types).map(([v,t])=>`<option value="${v}" ${params.get('type')===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="button" type="submit">Find services →</button></form><div class="notice warning">Demonstration service entries are not verified emergency contacts. Paid promotion is clearly labelled; hospitals, police and bus stations are not sponsored.</div><div class="service-grid">${items.map(serviceCard).join('')||empty('No matching services','Try another service type or search term.')}</div><section class="section"><h2>On the local map</h2><div id="services-map" class="map"></div></section></div>`;}
function bindServices(){$('#services-filter').onsubmit=e=>{e.preventDefault();go('services?'+new URLSearchParams(values(e.target)));};makeMap('services-map',[],state.serviceItems);}
function care(){return `<div class="container prose">${pageHead('Let the wild stay wonderful.','The places we love need a little love back. A thoughtful visit makes all the difference.','OUR NATURE PROMISE')}<div class="nature-art" style="border-radius:20px;min-height:290px"><span>Take a breath. Leave a lighter footprint.</span></div><h2>Carry it in. Carry it home.</h2><p>Bring a reusable bottle and a bag for every piece of waste, including food scraps. Leave rivers and streams free of soap, shampoo and litter.</p><h2>Follow the trail. Respect the boundaries.</h2><p>Stay on established paths. Ask before entering private land, temples, farms or community spaces. Follow local signs and closures, and do not share access to protected or sensitive wildlife areas.</p><h2>Be a guest in someone’s home.</h2><p>Ask permission before photographing people. Dress respectfully at religious sites, keep music low, and give local life space to continue. Choose local shops and agree guide or driver prices in advance.</p><h2>Let wildlife be wild.</h2><p>Watch quietly from a distance. Never feed, touch or chase animals, pick plants, take natural souvenirs, light fires, or fly a drone where it could disturb wildlife or people.</p><h2>Let safety set the pace.</h2><p>Confirm access and weather before leaving. Water levels can change rapidly: a peaceful pool is not a guarantee that swimming is safe. Tell someone your route, carry water, and return with daylight to spare.</p><h2>Share with care.</h2><p>Publish accurate directions, meaningful conservation advice and only photos and contact details you have permission to share. Report outdated information so the next traveller can make a better decision.</p><div class="cta-panel"><div><h3>A small promise. A lasting difference.</h3><p>Keep the place special for the next person, and everyone who calls it home.</p></div><a class="button lime" href="#explore">Explore thoughtfully ↗</a></div></div>`;}
function advertise(){return `<div class="container">${pageHead('Local places. Local possibilities.','Help thoughtful travellers find your shop, rental service, tuk-tuk or guiding business.','FOR LOCAL BUSINESSES')}<div class="planner-layout"><div><div class="form-section"><h2>A simple, human process.</h2><ol><li>Tell the administrator about your business below.</li><li>The administrator contacts you to discuss eligibility, dates and a price.</li><li>Agree and make payment offline directly with the administrator.</li><li>The administrator records the payment and activates a clearly labelled paid promotion.</li></ol><div class="notice">Submitting this form does not publish a promotion or take payment. There is no online checkout. Never enter card or bank details here.</div><p>Promotion expires at the agreed end date. Hospitals, police stations and bus stations are essential information and cannot buy sponsored placement.</p></div></div><form id="advertise-form" class="form-section"><h2>Tell us a little about your business</h2><div class="form-grid">${field('business_name','Business name *','','required maxlength="160"')}${field('contact_name','Your name *','','required maxlength="100"')}${field('email','Email *','','type="email" required maxlength="190"')}${field('phone','Phone *','','required maxlength="50"')}${area('message','Business type, location & what you would like to promote *','','required minlength="10" maxlength="3000"')}</div><div class="form-error" role="alert"></div><button class="button" type="submit">Send advertising inquiry ↗</button></form></div></div>`;}
function bindAdvertise(){$('#advertise-form').onsubmit=e=>{e.preventDefault();submit(e.target,'advertise',values(e.target),()=>{e.target.reset();toast('Inquiry received. The administrator will contact you to discuss offline arrangements.');});};}
function parseRoute(){const raw=location.hash.replace(/^#/,'');const cut=raw.indexOf('?');const path=cut<0?raw:raw.slice(0,cut);const query=cut<0?'':raw.slice(cut+1);const parts=path.split('/').filter(Boolean);return{name:parts[0]||'home',id:parts[1]||'',params:new URLSearchParams(query)};}
async function resolve(route){switch(route.name){
case 'home':return[await home(),bindHome];
case 'explore':return[await explore(route.params),bindExplore];
case 'place':return[await detail(route.id),bindDetail];
case 'planner':return[await planner(),bindPlanner];
case 'submit':return[await placeForm(route.id),bindPlaceForm];
case 'services':return[await services(route.params),bindServices];
case 'care':return[care(),null];
case 'advertise':return[advertise(),bindAdvertise];
case 'login':return[auth(false),()=>bindAuth(false)];
case 'register':return[auth(true),()=>bindAuth(true)];
case 'account':case 'saved':case 'plans':case 'profile':return[await account(route.name),()=>bindAccount(route.name)];
case 'admin':{const section=adminSections.some(([key])=>key===route.id)?route.id:'overview';return[await admin(section),()=>bindAdmin(section)];}
default:return[`<div class="container">${pageHead('That path leads nowhere.','The page you asked for does not exist.','LOST?')}${empty('Nothing here','This link may be out of date.','explore','Discover places')}</div>`,null];}}
async function render(){const token=++state.routeToken;const route=parseRoute();nav();const main=$('#main-content');main.innerHTML='<div class="loading">Finding your next escape…</div>';let html,bind;
try{[html,bind]=await resolve(route);}
catch(error){if(token!==state.routeToken)return;
if(error.status===401){try{Object.assign(state,await api('session'));}catch(ignored){}state.user=null;nav();main.innerHTML=auth(false);bindAuth(false);toast('Your session has ended. Please sign in again.');return;}
main.innerHTML=`<div class="container">${pageHead('We could not load this page.',error.message||'Please try again in a moment.','SOMETHING WENT WRONG')}${empty('Nothing to show','The server did not return this content.','home','Back to home')}</div>`;return;}
if(token!==state.routeToken)return;main.innerHTML=html;
try{if(bind)bind();}catch(error){toast(error.message||'Part of this page could not start.',true);}
nav();}
function bindShell(){$('#menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open?'true':'false');};
$('.modal-close').onclick=closeModal;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
window.addEventListener('hashchange',()=>{closeModal();render();});}
const adminSections=[['overview','Overview'],['places','Submissions'],['services','Services'],['users','Travellers'],['reports','Reports'],['advertising','Inquiries'],['payments','Sponsorships']];
const essentialTypes=['hospital','police','bus_station'];
const dash=v=>(v===null||v===undefined||v==='')?'—':esc(String(v));
const day=v=>v?esc(String(v).slice(0,10)):'—';
const money=v=>'LKR '+Number(v||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});
function adminTabs(active){return `<div class="tabs">${adminSections.map(([key,label])=>`<a href="#admin/${key}" class="${active===key?'active':''}">${esc(label)}</a>`).join('')}</div>`;}
function adminTable(headings,rows,message){
  if(!rows.length)return `<div class="empty"><h3>Nothing to show</h3><p>${esc(message)}</p></div>`;
  return `<div class="table-wrap"><table><thead><tr>${headings.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
}
function rejectPlace(id){
  modal(`<h2>Reject this submission</h2><p>Explain what needs fixing. The contributor sees this note on their own place.</p><form id="reject-form"><label class="full">Reason<textarea name="moderation_note" required minlength="4" maxlength="3000" placeholder="For example: the access directions need a landowner permission note."></textarea></label><div class="form-actions"><button class="button danger" type="submit">Send rejection</button><button class="button secondary" type="button" id="cancel-reject">Cancel</button></div></form>`,()=>{
    $('#cancel-reject').onclick=closeModal;
    $('#reject-form').onsubmit=e=>{e.preventDefault();submit(e.target,'moderate_place',{id,status:'rejected',...values(e.target)},()=>{closeModal();toast('Submission rejected with feedback.');render();});};
  });
}
function serviceForm(service){
  const s=service||{}, places=(state.admin&&state.admin.places)||[];
  modal(`<h2>${s.id?'Edit service':'Add a local service'}</h2><form id="service-form"><div class="form-grid">
${field('name','Name',s.name||'','required maxlength="160"')}
<label>Type<select name="type">${Object.entries(types).map(([value,label])=>`<option value="${value}" ${s.type===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>
${field('phone','Phone',s.phone||'','maxlength="60"')}
${field('website','Website',s.website||'','maxlength="500" placeholder="https://"')}
${field('address','Address',s.address||'','maxlength="255"')}
<label>Attached place<select name="place_id"><option value="">Not tied to a place</option>${places.map(p=>`<option value="${p.id}" ${String(s.place_id||'')===String(p.id)?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>
${field('latitude','Latitude',s.latitude??'','type="number" step="any" min="-90" max="90"')}
${field('longitude','Longitude',s.longitude??'','type="number" step="any" min="-180" max="180"')}
${area('description','Description',s.description||'','maxlength="3000"')}
</div><p class="help">Hospitals, police stations and bus stations are essential services and can never be sponsored.</p><div class="form-actions"><button class="button" type="submit">Save service</button><button class="button secondary" type="button" id="cancel-service">Cancel</button></div></form>`,()=>{
    $('#cancel-service').onclick=closeModal;
    $('#service-form').onsubmit=e=>{e.preventDefault();const data=values(e.target);if(s.id)data.id=s.id;submit(e.target,'save_service',data,()=>{closeModal();toast('Service saved.');render();});};
  });
}
async function admin(section){
  if(!state.user)return auth(false);
  if(state.user.role!=='admin')return `<div class="container">${pageHead('Administrators only.','This area manages submissions, services, travellers and sponsorships.','ADMIN')}${empty('No access','Your account does not have administrator permissions.','explore','Discover places')}</div>`;
  const data=state.admin=await api('admin_dashboard');
  const stats=data.stats;
  let body='';
  if(section==='overview'){
    const attention=data.places.filter(p=>p.status==='pending');
    body=`<div class="stats">
<div class="stat"><strong>${stats.pending}</strong><span>Awaiting review</span></div>
<div class="stat"><strong>${stats.approved}</strong><span>Published places</span></div>
<div class="stat"><strong>${stats.users}</strong><span>Registered people</span></div>
<div class="stat"><strong>${stats.services}</strong><span>Local services</span></div>
<div class="stat"><strong>${stats.reports}</strong><span>Open reports</span></div>
<div class="stat"><strong>${stats.advertising}</strong><span>Open inquiries</span></div>
</div>
<div class="form-section" style="margin-top:24px"><h2>Needs your attention</h2>${attention.length?`<p>${attention.length} submission${attention.length===1?'':'s'} waiting for review.</p><a class="button" href="#admin/places">Review submissions →</a>`:'<p>Nothing is waiting for review. Reports and inquiries are on their own tabs.</p>'}</div>`;
  }else if(section==='places'){
    body=adminTable(['Place','Contributor','Status','Updated','Actions'],data.places.map(p=>`<tr>
<td><strong>${esc(p.title)}</strong><small>${esc(p.category)} · ${esc(p.region)}${p.is_demo?' · demonstration entry':''}</small></td>
<td>${dash(p.author_name)}</td>
<td>${badge(p.status)}${p.moderation_note?`<small>${esc(p.moderation_note)}</small>`:''}</td>
<td>${day(p.updated_at)}</td>
<td><a class="button secondary small" href="#place/${p.id}">View</a><a class="button secondary small" href="#submit/${p.id}">Edit</a>${p.status!=='approved'?`<button class="button small" data-approve="${p.id}">Approve</button>`:''}${p.status!=='rejected'?`<button class="button danger small" data-reject="${p.id}">Reject</button>`:''}</td></tr>`),'No places have been submitted yet.');
  }else if(section==='services'){
    body=`<div class="toolbar"><p>Essential services stay unsponsored. Paid promotions are recorded on the Sponsorships tab.</p><button class="button" id="add-service-btn">Add a service +</button></div>`+
      adminTable(['Service','Type','Attached place','Contact','Promotion','Actions'],data.services.map(s=>`<tr>
<td><strong>${esc(s.name)}</strong><small>${esc(s.description||'')}</small></td>
<td>${badge(types[s.type]||s.type)}</td>
<td>${dash(s.place_title)}</td>
<td>${dash(s.phone)}${s.website?`<small><a href="${esc(safeUrl(s.website))}" target="_blank" rel="noopener noreferrer">Website ↗</a></small>`:''}</td>
<td>${Number(s.is_sponsored)?`<span class="badge sponsored">Paid promotion</span><small>Until ${day(s.paid_until)}</small>`:(essentialTypes.includes(s.type)?'<small>Essential service</small>':'<small>Not sponsored</small>')}</td>
<td><button class="button secondary small" data-edit-service="${s.id}">Edit</button><button class="button danger small" data-delete-service="${s.id}">Delete</button></td></tr>`),'No services have been added yet.');
  }else if(section==='users'){
    body=adminTable(['Person','Role','Status','Joined','Actions'],data.users.map(u=>`<tr>
<td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td>
<td>${badge(u.role)}</td>
<td>${badge(u.status)}</td>
<td>${day(u.created_at)}</td>
<td>${u.role==='admin'?'<small>Administrator accounts cannot be changed here.</small>':`<button class="button ${u.status==='active'?'danger ':''}small" data-user="${u.id}" data-status="${u.status==='active'?'suspended':'active'}">${u.status==='active'?'Suspend':'Reactivate'}</button>`}</td></tr>`),'No travellers have registered yet.');
  }else if(section==='reports'){
    body=adminTable(['Place','What was reported','Reported by','Status','When','Actions'],data.reports.map(r=>`<tr>
<td><a class="text-link" href="#place/${r.place_id}">${esc(r.place_title)}</a></td>
<td><small>${esc(r.reason)}</small></td>
<td>${dash(r.reporter_name)}</td>
<td>${badge(r.status)}</td>
<td>${day(r.created_at)}</td>
<td>${r.status==='new'?`<button class="button small" data-report="${r.id}" data-status="resolved">Resolve</button><button class="button secondary small" data-report="${r.id}" data-status="dismissed">Dismiss</button>`:'<small>Closed</small>'}</td></tr>`),'No one has reported a place.');
  }else if(section==='advertising'){
    body=adminTable(['Business','Contact','About','Status','When','Actions'],data.advertising.map(a=>`<tr>
<td><strong>${esc(a.business_name)}</strong><small>${esc(a.message)}</small></td>
<td>${esc(a.contact_name)}<small><a href="mailto:${esc(a.email)}">${esc(a.email)}</a></small><small>${esc(a.phone)}</small></td>
<td>${dash(a.place_title)}</td>
<td>${badge(a.status)}</td>
<td>${day(a.created_at)}</td>
<td>${a.status!=='contacted'?`<button class="button secondary small" data-advert="${a.id}" data-status="contacted">Mark contacted</button>`:''}${a.status!=='closed'?`<button class="button small" data-advert="${a.id}" data-status="closed">Close</button>`:''}</td></tr>`),'No business has sent an inquiry yet.');
  }else{
    const sponsorable=data.services.filter(s=>!essentialTypes.includes(s.type));
    body=`<form id="payment-form" class="form-section"><h2>Record an offline payment</h2><p>Money is collected outside this system. Recording a payment whose dates cover today switches on the sponsored label automatically.</p>
${sponsorable.length?`<div class="form-grid">
<label>Service<select name="service_id" required>${sponsorable.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(types[s.type]||s.type)}</option>`).join('')}</select></label>
${field('amount','Amount (LKR)','','required type="number" min="0.01" step="0.01"')}
${field('reference','Receipt reference','','required maxlength="190"')}
${field('paid_on','Payment date','','required type="date"')}
${field('starts_on','Promotion starts','','required type="date"')}
${field('ends_on','Promotion ends','','required type="date"')}
${area('notes','Private notes','','maxlength="3000"')}
</div><div class="form-actions"><button class="button" type="submit">Record payment</button></div>`:'<div class="notice">Add a non-essential service first; hospitals, police stations and bus stations cannot be sponsored.</div>'}</form>`+
      adminTable(['Service','Amount','Reference','Paid on','Promotion window','Status','Actions'],data.payments.map(p=>`<tr>
<td>${dash(p.service_name)}${p.service_id?'':'<small>Service since removed</small>'}</td>
<td>${money(p.amount)}</td>
<td><small>${esc(p.reference)}</small>${p.notes?`<small>${esc(p.notes)}</small>`:''}</td>
<td>${day(p.paid_on)}</td>
<td>${day(p.starts_on)} → ${day(p.ends_on)}</td>
<td>${badge(p.status)}</td>
<td>${p.status==='active'?`<button class="button danger small" data-cancel-payment="${p.id}">Cancel</button>`:'<small>Cancelled</small>'}</td></tr>`),'No payments have been recorded.');
  }
  return `<div class="container">${pageHead('Administration','Review submissions, manage local services and record offline sponsorships.','ADMIN')}${adminTabs(section)}${body}</div>`;
}
function bindAdmin(section){
  if(!state.user){bindAuth(false);return;}
  if(state.user.role!=='admin')return;
  const act=(message,call)=>async()=>{try{await call();toast(message);render();}catch(error){toast(error.message,true);}};
  if(section==='places'){
    $$('[data-approve]').forEach(b=>b.onclick=()=>confirmAction('Approve this place?','It appears in public discovery straight away.',async()=>{await api('moderate_place',{id:Number(b.dataset.approve),status:'approved',moderation_note:''});toast('Place approved.');render();}));
    $$('[data-reject]').forEach(b=>b.onclick=()=>rejectPlace(Number(b.dataset.reject)));
  }else if(section==='services'){
    $('#add-service-btn').onclick=()=>serviceForm(null);
    $$('[data-edit-service]').forEach(b=>b.onclick=()=>serviceForm(state.admin.services.find(s=>String(s.id)===b.dataset.editService)));
    $$('[data-delete-service]').forEach(b=>b.onclick=()=>confirmAction('Delete this service?','Recorded payments are kept for your records and keep the service name.',async()=>{await api('delete_service',{id:Number(b.dataset.deleteService)});toast('Service deleted.');render();}));
  }else if(section==='users'){
    $$('[data-user]').forEach(b=>b.onclick=()=>{const suspending=b.dataset.status==='suspended';
      confirmAction(suspending?'Suspend this traveller?':'Reactivate this traveller?',suspending?'They cannot sign in or submit places until reactivated. Their content stays in place.':'They can sign in and contribute again.',async()=>{await api('user_status',{id:Number(b.dataset.user),status:b.dataset.status});toast(suspending?'Traveller suspended.':'Traveller reactivated.');render();});});
  }else if(section==='reports'){
    $$('[data-report]').forEach(b=>b.onclick=act('Report closed.',()=>api('resolve_report',{id:Number(b.dataset.report),status:b.dataset.status})));
  }else if(section==='advertising'){
    $$('[data-advert]').forEach(b=>b.onclick=act('Inquiry updated.',()=>api('advertising_status',{id:Number(b.dataset.advert),status:b.dataset.status})));
  }else if(section==='payments'){
    const form=$('#payment-form');
    if(form&&$('[type=submit]',form))form.onsubmit=e=>{e.preventDefault();submit(e.target,'record_payment',values(e.target),()=>{toast('Payment recorded.');render();});};
    $$('[data-cancel-payment]').forEach(b=>b.onclick=()=>confirmAction('Cancel this sponsorship?','The promotion stops immediately. The payment record is kept.',async()=>{await api('cancel_payment',{id:Number(b.dataset.cancelPayment)});toast('Sponsorship cancelled.');render();}));
  }
}
(async function boot(){try{Object.assign(state,await api('session'));}catch(error){}
bindShell();await render();})();
